CREATE FUNCTION public.apply_payment_event(_event_id text,_env text,_type text,_occurred timestamptz,_data jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; sub_id text; BEGIN IF _env NOT IN ('sandbox','live') THEN RAISE EXCEPTION 'invalid environment'; END IF; INSERT INTO public.payment_events(event_id,environment,event_type,occurred_at) VALUES(_event_id,_env,_type,_occurred) ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN; END IF;
IF _type LIKE 'subscription.%' THEN sub_id:=_data->>'id'; SELECT user_id INTO uid FROM public.subscriptions WHERE paddle_subscription_id=sub_id AND environment=_env; IF uid IS NULL THEN uid:=NULLIF(_data->'custom_data'->>'userId','')::uuid; END IF; IF uid IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=uid) THEN RAISE EXCEPTION 'unattributed subscription'; END IF;
INSERT INTO public.subscriptions(user_id,paddle_subscription_id,paddle_customer_id,product_id,price_id,status,current_period_start,current_period_end,cancel_at_period_end,environment,last_event_at) VALUES(uid,sub_id,_data->>'customer_id',_data->>'app_product_id',_data->>'app_price_id',_data->>'status',NULLIF(_data->'current_billing_period'->>'starts_at','')::timestamptz,NULLIF(_data->'current_billing_period'->>'ends_at','')::timestamptz,COALESCE(_data->'scheduled_change'->>'action'='cancel',false),_env,_occurred) ON CONFLICT(paddle_subscription_id) DO UPDATE SET status=EXCLUDED.status,current_period_start=COALESCE(EXCLUDED.current_period_start,subscriptions.current_period_start),current_period_end=COALESCE(EXCLUDED.current_period_end,subscriptions.current_period_end),cancel_at_period_end=EXCLUDED.cancel_at_period_end,price_id=EXCLUDED.price_id,last_event_at=EXCLUDED.last_event_at,updated_at=now() WHERE subscriptions.environment=_env AND subscriptions.user_id=uid AND subscriptions.last_event_at<=_occurred;
ELSIF _type LIKE 'transaction.%' THEN sub_id:=_data->>'subscription_id'; SELECT user_id INTO uid FROM public.subscriptions WHERE paddle_subscription_id=sub_id AND environment=_env; IF uid IS NULL THEN uid:=NULLIF(_data->'custom_data'->>'userId','')::uuid; END IF; IF uid IS NULL THEN RAISE EXCEPTION 'unattributed payment'; END IF; INSERT INTO public.payment_history(id,user_id,subscription_id,status,amount_minor,currency,environment,occurred_at) VALUES(_data->>'id',uid,sub_id,_data->>'status',NULLIF(_data->'details'->'totals'->>'total','')::bigint,_data->>'currency_code',_env,_occurred) ON CONFLICT(id) DO UPDATE SET status=EXCLUDED.status,amount_minor=EXCLUDED.amount_minor,currency=EXCLUDED.currency,occurred_at=EXCLUDED.occurred_at WHERE payment_history.environment=_env AND payment_history.occurred_at<=_occurred;
END IF; END $$; REVOKE ALL ON FUNCTION public.apply_payment_event(text,text,text,timestamptz,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.apply_payment_event(text,text,text,timestamptz,jsonb) TO service_role;